var hum = Number(msg.payload);
var highSet = Number(flow.get('hum_highThreshold')) || 90;
var lowSet  = Number(flow.get('hum_lowThreshold'))  || 70;
var override = Number(flow.get('hum_overrideMode')) || 0;

// Alert thresholds are ±5% beyond setpoints
var alertHigh = highSet + 5;
var alertLow  = lowSet  - 5;

// If override is active (1=OFF forced, 2=ON forced),
// suppress alerts — operator is intentionally in control
if (override !== 0) {
    node.status({ fill:'yellow', shape:'dot',
        text:'Override active (' + override + ') — alerts suppressed' });
    return null;
}

node.status({ fill:'blue', shape:'dot',
    text:'RH:' + hum + ' AlertHi:' + alertHigh + ' AlertLo:' + alertLow });

msg.hum       = hum;
msg.alertHigh = alertHigh;
msg.alertLow  = alertLow;
msg.highSet   = highSet;
msg.lowSet    = lowSet;

// Output 1: check high | Output 2: check low
return [msg, msg];

var hum = msg.hum;
var alertHigh = msg.alertHigh;

if (hum > alertHigh) {
    if (!flow.get('hum_high_timing_started')) {
        flow.set('hum_high_timing_started', Date.now());
        node.status({
            fill: 'yellow', shape: 'dot',
            text: 'HIGH breach started: ' + hum + '% > ' + alertHigh + '%'
        });
    }
    var elapsed = (Date.now() - flow.get('hum_high_timing_started')) / 60000;
    var lastAlert = flow.get('hum_high_last_alert') || 0;
    var minsSinceAlert = (Date.now() - lastAlert) / 60000;

    // Fire if: 10 min elapsed AND (never alerted OR 5 min since last alert)
    if (elapsed >= 10 && (lastAlert === 0 || minsSinceAlert >= 5)) {
        flow.set('hum_high_last_alert', Date.now());
        node.status({
            fill: 'red', shape: 'dot',
            text: 'ALERT: ' + hum + '% — ' + Math.round(elapsed) + ' min'
        });
        return msg;
    }
} else {
    if (flow.get('hum_high_timing_started')) {
        flow.set('hum_high_timing_started', null);
        flow.set('hum_high_last_alert', 0);
        node.status({ fill: 'green', shape: 'dot', text: 'Recovered: ' + hum + '%' });
    }
}
return null;

var hum = msg.hum;
var alertLow = msg.alertLow;

if (hum < alertLow) {
    if (!flow.get('hum_low_timing_started')) {
        flow.set('hum_low_timing_started', Date.now());
        node.status({
            fill: 'yellow', shape: 'dot',
            text: 'LOW breach started: ' + hum + '% < ' + alertLow + '%'
        });
    }
    var elapsed = (Date.now() - flow.get('hum_low_timing_started')) / 60000;
    var lastAlert = flow.get('hum_low_last_alert') || 0;
    var minsSinceAlert = (Date.now() - lastAlert) / 60000;

    if (elapsed >= 10 && (lastAlert === 0 || minsSinceAlert >= 5)) {
        flow.set('hum_low_last_alert', Date.now());
        node.status({
            fill: 'red', shape: 'dot',
            text: 'ALERT: ' + hum + '% — ' + Math.round(elapsed) + ' min'
        });
        return msg;
    }
} else {
    if (flow.get('hum_low_timing_started')) {
        flow.set('hum_low_timing_started', null);
        flow.set('hum_low_last_alert', 0);
        node.status({ fill: 'green', shape: 'dot', text: 'Recovered: ' + hum + '%' });
    }
}
return null;

var highSet = msg.highSet || Number(flow.get('hum_highThreshold')) || 90;
var alertHigh = msg.alertHigh || (highSet + 5);
msg.payload = {
    title: '⚠️ MushRm Humidity HIGH',
    body: 'Fruiting Front: ' + msg.hum + '% for 10+ min (setpoint ' + highSet + '%, alert at ' + alertHigh + '%). Check humidifier/fan.'
};
return msg;

var lowSet = msg.lowSet || Number(flow.get('hum_lowThreshold')) || 70;
var alertLow = msg.alertLow || (lowSet - 5);
msg.payload = {
    title: '⚠️ MushRm Humidity LOW',
    body: 'Fruiting Front: ' + msg.hum + '% for 10+ min (setpoint ' + lowSet + '%, alert at ' + alertLow + '%). Check humidifier/fan.'
};
return msg;

var mins = Number(flow.get('snooze_duration')) || 30;
flow.set('snooze_active', true);
flow.set('snooze_until', Date.now() + (mins * 60000));
node.warn('Snooze activated for ' + mins + ' min');

// Send close to whichever gates have their switch ON
var msgs = [null, null];
if (flow.get('hum_alert_enabled', 'file'))  msgs[0] = { topic: 'control', payload: 'close' };
if (flow.get('scd1_alert_enabled', 'file')) msgs[1] = { topic: 'control', payload: 'close' };
return msgs;

flow.set('snooze_active', false);
flow.set('snooze_until', 0);
node.warn('Snooze cancelled');

// Reopen only gates that have their switch ON
var msgs = [null, null];
if (flow.get('hum_alert_enabled', 'file'))  msgs[0] = { topic: 'control', payload: 'open' };
if (flow.get('scd1_alert_enabled', 'file')) msgs[1] = { topic: 'control', payload: 'open' };
return msgs;

var snoozeActive = flow.get('snooze_active') || false;
var snoozeUntil = flow.get('snooze_until') || 0;

// Auto-expire
if (snoozeActive && Date.now() > snoozeUntil) {
    flow.set('snooze_active', false);
    flow.set('snooze_until', 0);
    snoozeActive = false;
    node.warn('Snooze expired — reopening enabled gates');

    // Reopen only gates with switch ON
    var reopenMsgs = [null, null];
    if (flow.get('hum_alert_enabled', 'file'))  reopenMsgs[0] = { topic: 'control', payload: 'open' };
    if (flow.get('scd1_alert_enabled', 'file')) reopenMsgs[1] = { topic: 'control', payload: 'open' };
    node.send(reopenMsgs);
}

var minsLeft = snoozeActive ? Math.ceil((snoozeUntil - Date.now()) / 60000) : 0;

node.status({
    fill: snoozeActive ? 'yellow' : 'green',
    shape: 'dot',
    text: snoozeActive ? 'Snoozed: ' + minsLeft + ' min left' : 'No snooze active'
});

// Output 3: snooze LED update only
return [null, null, { payload: snoozeActive ? 'ON' : 'OFF' }];

var enabled = msg.payload;
flow.set('hum_alert_enabled', enabled, 'file');

// Send open/close directly to humidity gate
msg.topic = 'control';
msg.payload = enabled ? 'open' : 'close';

// Also update LED
var ledMsg = { payload: enabled ? 'ON' : 'OFF' };
return [msg, ledMsg];

var enabled = msg.payload;
flow.set('scd1_alert_enabled', enabled, 'file');

// Send open/close directly to SCD1 gate
msg.topic = 'control';
msg.payload = enabled ? 'open' : 'close';

// Also update LED
var ledMsg = { payload: enabled ? 'ON' : 'OFF' };
return [msg, ledMsg];

var humEnabled = flow.get('hum_alert_enabled', 'file');
var scd1Enabled = flow.get('scd1_alert_enabled', 'file');

// Default to true if never set
if (humEnabled === null || humEnabled === undefined) humEnabled = true;
if (scd1Enabled === null || scd1Enabled === undefined) scd1Enabled = true;

var humMsg = { topic: 'control', payload: humEnabled ? 'open' : 'close' };
var scd1Msg = { topic: 'control', payload: scd1Enabled ? 'open' : 'close' };

return [humMsg, scd1Msg];

var now = Date.now();
var wasInGap = flow.get('scd1_in_gap') || false;

// Always update last seen
flow.set('scd1_last_seen', now);

if (wasInGap) {
    // Sensor just came back — calculate outage duration
    var gapStarted = flow.get('scd1_gap_started') || now;
    var outageMin = Math.round((now - gapStarted) / 60000 * 10) / 10;

    // Clear gap state
    flow.set('scd1_in_gap', false);
    flow.set('scd1_alarm_sent', false);
    flow.set('scd1_gap_started', null);

    msg.outageMinutes = outageMin;
    msg.recoveryTime = new Date(now).toISOString();
    node.warn('SCD1 recovered after ' + outageMin + ' min outage');
    return msg;  // send to recovery logger
}

// Normal heartbeat — no output needed
return null;

var lastSeen = flow.get('scd1_last_seen');
var now = Date.now();

if (!lastSeen) {
    node.warn('SCD1 watchdog: no baseline yet, skipping');
    return null;
}

var gapMs = now - lastSeen;
var gapMin = Math.round(gapMs / 60000 * 10) / 10;

if (gapMin < 2) {
    return null;
}

var alreadyInGap = flow.get('scd1_in_gap') || false;
if (!alreadyInGap) {
    flow.set('scd1_in_gap', true);
    flow.set('scd1_gap_started', lastSeen);
}

msg.gapMinutes = gapMin;
msg.lastSeen = new Date(lastSeen).toISOString();

var alarmSent = flow.get('scd1_alarm_sent') || false;
if (gapMin >= 10 && !alarmSent) {
    return [msg, msg];
} else {
    return [msg, null];
}

flow.set('scd1_alarm_sent', true);
node.warn('SCD1 ALARM: gap of ' + msg.gapMinutes + ' min — sending RemoteRED notification');
return msg;

msg.payload = {
    title: '⚠️ MushRm SCD1 Sensor Lost',
    body: 'Fruiting Front SCD1 has not reported for ' + msg.gapMinutes + ' min. Last seen: ' + msg.lastSeen + '. EZO1 fallback now active. Check LoRa link / XIAO unit.'
};
return msg;

var gapMin = msg.gapMinutes;
var line = 'sensor_watchdog,sensor=SCD1_FruitingFront,location=fruiting_front gap_minutes=' + gapMin + ',event="dropout"';
msg.payload = line;
return msg;

var outageMin = msg.outageMinutes;
var line = 'sensor_watchdog,sensor=SCD1_FruitingFront,location=fruiting_front outage_minutes=' + outageMin + ',event="recovery"';
msg.payload = line;
return msg;

// Only pass through when SCD1 is in a gap
var inGap = flow.get('scd1_in_gap') || false;

if (!inGap) {
    node.status({ fill:'grey', shape:'ring', text:'Standby' });
    return null;
}

// Convert payload to rounded number matching SCD1 format
msg.payload = Math.round(Number(msg.payload) * 100) / 100;
msg.source = 'EZO1_fallback';

node.status({ fill:'yellow', shape:'dot', text:'ACTIVE — feeding as SCD1 backup: ' + msg.payload + '%' });
return msg;

msg.payload = {
    title: '⚠️ MushRm EZO1 Fallback Active',
    body: 'SCD1 offline — EZO1 is now feeding humidity control. Values may differ slightly. Outage started: ' + msg.lastSeen
};
return msg;

msg.payload = {
    title: '✅ MushRm SCD1 Restored',
    body: 'SCD1 is back online after ' + msg.outageMinutes + ' min. EZO1 fallback deactivated. Humidity control restored to SCD1.'
};
return msg;
